const r=(a,c,d=2)=>+(a+Math.random()*(c-a)).toFixed(d);
const opt=(t,ok)=>({t,ok:ok?1:0}), mcq=(tag,q,ok,bad,why)=>({tag,q,opts:[opt(ok,1),...bad.map(x=>opt(x))],why});
