const ax=(id,n,es,eu)=>`<a href="azterketak.html#${id}-${n}">${id.replace('-o',' ohikoa').replace('-e',' ez-ohikoa')} · ${n}</a>`;
const frac=(a,c)=>`<span class="frac"><span>${a}</span><span>${c}</span></span>`;
const tag={rx:b('Redox','Erredoxa'),bal:b('Ajuste','Doiketa'),pila:b('Pilas','Pilak'),ner:b('Nernst','Nernst'),ther:b('Termodinámica','Termodinamika'),far:b('Faraday','Faraday'),corr:b('Corrosión','Korrosioa')};
const svgRedox=b(`<svg viewBox="0 0 420 150" role="img" aria-label="Transferencia electrónica"><defs><marker id="redox-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10z" fill="var(--accent)"/></marker></defs><rect x="18" y="34" width="154" height="82" rx="12" fill="var(--surface)" stroke="var(--c-azido)" stroke-width="2"/><rect x="248" y="34" width="154" height="82" rx="12" fill="var(--surface)" stroke="var(--c-oreka)" stroke-width="2"/><text x="95" y="65" text-anchor="middle" class="svgtxt" font-size="17">reductor</text><text x="95" y="92" text-anchor="middle" class="svgmono" font-size="17">M → Mⁿ⁺ + ne⁻</text><text x="325" y="65" text-anchor="middle" class="svgtxt" font-size="17">oxidante</text><text x="325" y="92" text-anchor="middle" class="svgmono" font-size="17">X + ne⁻ → Xⁿ⁻</text><path d="M174 74H244" stroke="var(--accent)" stroke-width="3" marker-end="url(#redox-arrow)"/><text x="209" y="61" text-anchor="middle" class="svgtxt" font-size="14">e⁻</text></svg>`,
 `<svg viewBox="0 0 420 150" role="img" aria-label="Elektroien transferentzia"><defs><marker id="redox-arrow-eu" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10z" fill="var(--accent)"/></marker></defs><rect x="18" y="34" width="154" height="82" rx="12" fill="var(--surface)" stroke="var(--c-azido)" stroke-width="2"/><rect x="248" y="34" width="154" height="82" rx="12" fill="var(--surface)" stroke="var(--c-oreka)" stroke-width="2"/><text x="95" y="65" text-anchor="middle" class="svgtxt" font-size="17">erreduktorea</text><text x="95" y="92" text-anchor="middle" class="svgmono" font-size="17">M → Mⁿ⁺ + ne⁻</text><text x="325" y="65" text-anchor="middle" class="svgtxt" font-size="17">oxidatzailea</text><text x="325" y="92" text-anchor="middle" class="svgmono" font-size="17">X + ne⁻ → Xⁿ⁻</text><path d="M174 74H244" stroke="var(--accent)" stroke-width="3" marker-end="url(#redox-arrow-eu)"/><text x="209" y="61" text-anchor="middle" class="svgtxt" font-size="14">e⁻</text></svg>`);
const svgCell=b(`<svg viewBox="0 0 420 185" role="img" aria-label="Pila de Daniell"><defs><marker id="cell-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10z" fill="var(--accent)"/></marker></defs><path d="M94 47V22H326V47" fill="none" stroke="var(--ink-2)" stroke-width="2"/><path d="M100 22H320" stroke="var(--accent)" stroke-width="3" marker-end="url(#cell-arrow)"/><text x="210" y="17" text-anchor="middle" class="svgtxt" font-size="15">e⁻ →</text><path d="M145 99Q145 139 176 139H244Q275 139 275 99" fill="none" stroke="var(--c-pila)" stroke-width="8"/><path d="M57 55V151Q57 162 68 162H150Q161 162 161 151V55M259 55V151Q259 162 270 162H352Q363 162 363 151V55" fill="var(--surface-2)" stroke="var(--line)" stroke-width="2"/><line x1="107" y1="44" x2="107" y2="143" stroke="var(--ink-2)" stroke-width="5"/><line x1="313" y1="44" x2="313" y2="143" stroke="var(--ink-2)" stroke-width="5"/><text x="107" y="91" text-anchor="middle" class="svgmono" font-size="16">Zn</text><text x="313" y="91" text-anchor="middle" class="svgmono" font-size="16">Cu</text><text x="107" y="179" text-anchor="middle" class="svgtxt" font-size="14">ánodo (−)</text><text x="313" y="179" text-anchor="middle" class="svgtxt" font-size="14">cátodo (+)</text></svg>`,
 `<svg viewBox="0 0 420 185" role="img" aria-label="Daniell pila"><defs><marker id="cell-arrow-eu" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10z" fill="var(--accent)"/></marker></defs><path d="M94 47V22H326V47" fill="none" stroke="var(--ink-2)" stroke-width="2"/><path d="M100 22H320" stroke="var(--accent)" stroke-width="3" marker-end="url(#cell-arrow-eu)"/><text x="210" y="17" text-anchor="middle" class="svgtxt" font-size="15">e⁻ →</text><path d="M145 99Q145 139 176 139H244Q275 139 275 99" fill="none" stroke="var(--c-pila)" stroke-width="8"/><path d="M57 55V151Q57 162 68 162H150Q161 162 161 151V55M259 55V151Q259 162 270 162H352Q363 162 363 151V55" fill="var(--surface-2)" stroke="var(--line)" stroke-width="2"/><line x1="107" y1="44" x2="107" y2="143" stroke="var(--ink-2)" stroke-width="5"/><line x1="313" y1="44" x2="313" y2="143" stroke="var(--ink-2)" stroke-width="5"/><text x="107" y="91" text-anchor="middle" class="svgmono" font-size="16">Zn</text><text x="313" y="91" text-anchor="middle" class="svgmono" font-size="16">Cu</text><text x="107" y="179" text-anchor="middle" class="svgtxt" font-size="14">anodoa (−)</text><text x="313" y="179" text-anchor="middle" class="svgtxt" font-size="14">katodoa (+)</text></svg>`);

/* -------------------- galdera-sortak (8 item berri/saio) -------------------- */
function q1n(){return nq(tag.rx,b(`En ${MnO4}⁻ → Mn²⁺, ¿cuántos electrones gana cada Mn?`,`MnO₄⁻ → Mn²⁺ erreakzioan, zenbat elektroi irabazten ditu Mn bakoitzak?`),5,b('Mn pasa de +7 a +2: gana 5 e⁻ por átomo.','Mn +7tik +2ra doa: 5 e⁻ irabazten ditu atomo bakoitzeko.'),{abs:0,label:'e⁻'});}
const MnO4='MnO4';
function q1ox(){return mcq(tag.rx,b('En una oxidación, el número de oxidación…','Oxidazio batean, oxidazio-zenbakiak…'),b('aumenta porque la especie pierde electrones','gora egiten du, espezieak elektroiak galtzen dituelako'),[b('disminuye porque gana electrones','behera egiten du, elektroiak irabazten dituelako'),b('no cambia si hay transferencia de carga','ez da aldatzen karga-transferentzia badago'),b('es siempre positivo','beti positiboa da')],b('Pérdida de e⁻ = oxidación; el agente reductor es quien se oxida.','e⁻ galtzea = oxidazioa; erreduktorea oxidatzen dena da.'));}
function q2e(){return mcq(tag.pila,b('¿Qué representa E° de una semirreacción?','Zer adierazten du erdi-erreakzio baten E°-k?'),b('Un potencial de reducción referido al electrodo estándar de hidrógeno','Hidrogeno-elektrodo estandarrarekiko neurtutako erredukzio-potentziala'),[b('Una energía que se multiplica por el coeficiente estequiométrico','Koefiziente estekiometrikoaz biderkatzen den energia'),b('El potencial de oxidación en todos los casos','Oxidazio-potentziala kasu guztietan'),b('El potencial absoluto de una semicelda aislada','Isolatutako erdi-zelda baten potentzial absolutua')],b('Solo se miden diferencias; por convenio E°(H⁺/H₂)=0. E° no cambia al multiplicar la semirreacción.','Potentzial-diferentziak bakarrik neur daitezke; hitzarmenez E°(H⁺/H₂)=0. E° ez da aldatzen erdi-erreakzioa biderkatzean.'));}
function q2num(){const e=pick([1.10,1.103,0.46]),a=pick([-0.76,-0.763,-0.44]),ans=+(e-a).toFixed(3);return nq(tag.pila,b(`E°red(cátodo) = ${fix(e,3)} V y E°red(ánodo) = ${fix(a,3)} V. E°pila (V):`,`E°red(katodoa) = ${fix(e,3)} V eta E°red(anodoa) = ${fix(a,3)} V. E°pila (V):`),ans,b(`E°pila = E°cát − E°án = ${fix(e,3)} − (${fix(a,3)}) = ${fix(ans,3)} V.`,`E°pila = E°kat − E°an = ${fix(e,3)} − (${fix(a,3)}) = ${fix(ans,3)} V.`),{abs:.002});}
function q3n(){const c=pick([.1,.01,.001]),ans=+(S/2*Math.log10(1/c)).toFixed(4);return nq(tag.ner,b(`Para Zn²⁺ + 2e⁻ ⇌ Zn(s), E° = −0,763 V. Si [Zn²⁺] = ${num(c)}, calcula E (V).`,`Zn²⁺ + 2e⁻ ⇌ Zn(s), E° = −0,763 V. [Zn²⁺] = ${num(c)} bada, kalkulatu E (V).`),-0.763+S/2*Math.log10(c),b(`E = E° + (0,0592/2)log[Zn²⁺] = ${fix(-0.763+S/2*Math.log10(c),4)} V.`,`E = E° + (0,0592/2)log[Zn²⁺] = ${fix(-0.763+S/2*Math.log10(c),4)} V.`),{abs:.001});}
function q3why(){return mcq(tag.ner,b('En Cr₂O₇²⁻ + 14H⁺ + 6e⁻ ⇌ 2Cr³⁺ + 7H₂O, ¿qué término entra en Q?','Cr₂O₇²⁻ + 14H⁺ + 6e⁻ ⇌ 2Cr³⁺ + 7H₂O erreakzioan, zein sartzen da Q-n?'),b('[H⁺]¹⁴','[H⁺]¹⁴'),[b('La actividad de H₂O líquida','H₂O likidoaren aktibitatea'),b('La concentración de los electrones','Elektroien kontzentrazioa'),b('La cantidad de Pt','Pt kantitatea')],b('Q = [Cr³⁺]²/([Cr₂O₇²⁻][H⁺]¹⁴); los electrones y líquidos puros no aparecen.','Q = [Cr³⁺]²/([Cr₂O₇²⁻][H⁺]¹⁴); elektroiak eta likido puruak ez dira agertzen.'));}
function q4(){const n=pick([1,2,3]),e=pick([.8,1.1,.25]),dg=-n*F*e/1000;return nq(tag.ther,b(`Una pila tiene E° = ${fix(e,2)} V y transfiere ${n} mol e⁻ por mol de reacción. ΔG° (kJ·mol⁻¹):`,`Pila batek E° = ${fix(e,2)} V du eta erreakzio-mol bakoitzeko ${n} mol e⁻ transferitzen ditu. ΔG° (kJ·mol⁻¹):`),dg,b(`ΔG° = −nFE° = −${n}·96485·${fix(e,2)} = ${fix(dg,2)} kJ·mol⁻¹.`,`ΔG° = −nFE° = −${n}·96485·${fix(e,2)} = ${fix(dg,2)} kJ·mol⁻¹.`),{abs:.1});}
function q4mcq(){return mcq(tag.ther,b('Al multiplicar por 2 una reacción redox ajustada…','Doitutako erredox-erreakzio bat 2z biderkatzean…'),b('se duplican n y ΔG°, pero E° no cambia','n eta ΔG° bikoizten dira, baina E° ez da aldatzen'),[b('E° y K se duplican','E° eta K bikoizten dira'),b('E° se duplica y n no cambia','E° bikoizten da eta n ez da aldatzen'),b('K se reduce a la mitad','K erdira jaisten da')],b('El potencial es intensivo; ΔG° y la cantidad de electrones son extensivos respecto a la ecuación escrita.','Potentziala intentsiboa da; ΔG° eta elektroi kopurua ekuazio idatziaren araberakoak dira.'));}
function q5(){return mcq(tag.far,b('Una pila galvánica opera…','Pila galbaniko batek…'),b('espontáneamente: ánodo (−), cátodo (+), e⁻ del ánodo al cátodo','berez: anodoa (−), katodoa (+), e⁻ anodoatik katodora'),[b('con corriente externa: ánodo (+), cátodo (−)','kanpoko korrontearekin: anodoa (+), katodoa (−)'),b('espontáneamente: e⁻ del cátodo al ánodo','berez: e⁻ katodotik anodora'),b('sin puente salino ni circuito externo','gatz-zubirik eta kanpo-zirkuiturik gabe')],b('En una pila, oxidación en el ánodo y reducción en el cátodo; el puente mantiene electroneutralidad.','Pilan oxidazioa anodoan eta erredukzioa katodoan gertatzen dira; gatz-zubiak elektroneutraltasuna mantentzen du.'));}
function q5num(){const I=pick([.02,.05,.1]),t=pick([120,300,600]),q=I*t;return nq(tag.far,b(`Una pila entrega I = ${fix(I,2)} A durante ${t} s. ¿Qué carga Q (C) circula?`,`Pila batek I = ${fix(I,2)} A ematen du ${t} s-an. Zer karga Q (C) igarotzen da?`),q,b(`Q = It = ${fix(I,2)}·${t} = ${fix(q,2)} C.`,`Q = It = ${fix(I,2)}·${t} = ${fix(q,2)} C.`),{abs:.01,label:'C'});}
function q6(){return mcq(tag.corr,b('¿Por qué el galvanizado protege incluso si se raya la capa de zinc?','Zergatik babesten du galbanizazioak zink-geruza urratuta ere?'),b('El Zn, más fácilmente oxidable, actúa como ánodo de sacrificio','Zn-a, errazago oxidatzen dena, sakrifizio-anodo gisa aritzen da'),[b('El Fe deja de ser conductor','Fe-a eroale izateari uzten dio'),b('El Zn eleva E° del hierro','Zn-ak burdinaren E° handitzen du'),b('El oxígeno ya no puede reducirse','Oxigenoa ezin da erreduzitu')],b('Zn se oxida preferentemente; el hierro queda como cátodo (protección catódica).','Zn-a lehenago oxidatzen da; burdina katodo gisa babestuta geratzen da (babes katodikoa).'));}
function q1balance(){return mcq(tag.bal,b('Al ajustar una reacción redox en medio ácido, ¿con qué se ajustan O y H, respectivamente?','Ingurune azidoan erredox-erreakzio bat doitzean, zerekin doitzen dira O eta H, hurrenez hurren?'),b('Con H₂O y H⁺','H₂O-rekin eta H⁺-rekin'),[b('Con O₂ y H₂','O₂-rekin eta H₂-rekin'),b('Con OH⁻ y H₂O','OH⁻-rekin eta H₂O-rekin'),b('Solo con electrones','Elektroiekin bakarrik')],b('En medio ácido se ajusta O con H₂O y H con H⁺; los electrones ajustan la carga.','Ingurune azidoan O H₂O-rekin eta H H⁺-rekin doitzen dira; elektroiek karga doitzen dute.'));}
function q1basic(){return mcq(tag.bal,b('Tras ajustar semirreacciones en ácido, ¿qué paso permite obtener la ecuación final en medio básico?','Erdi-erreakzioak ingurune azidoan doitu ondoren, zer egin behar da ingurune basikoko ekuazioa lortzeko?'),b('Añadir OH⁻ a ambos lados para neutralizar H⁺ y simplificar agua','OH⁻ bi aldeetan gehitu H⁺ neutralizatzeko, eta ura sinplifikatu'),[b('Dejar H⁺ porque el ajuste ya terminó','H⁺ utzi, doiketa amaituta dagoelako'),b('Cambiar H⁺ por e⁻','H⁺ e⁻-z ordezkatu'),b('Añadir OH⁻ solo a los productos','OH⁻ produktuei bakarrik gehitu')],b('H⁺ + OH⁻ forma agua; luego se cancelan las moléculas de agua comunes.','H⁺ + OH⁻ → H₂O gertatzen da; ondoren, bi aldeetako ur molekulak ezeztatzen dira.'));}
function q1agents(){return mcq(tag.rx,b('En Fe²⁺ → Fe³⁺ + e⁻, ¿qué papel desempeña Fe²⁺?','Fe²⁺ → Fe³⁺ + e⁻ erreakzioan, zer eginkizun du Fe²⁺-k?'),b('Es el reductor porque pierde electrones y se oxida','Erreduktorea da, elektroiak galdu eta oxidatu egiten delako'),[b('Es el oxidante porque pierde electrones','Oxidatzailea da, elektroiak galtzen dituelako'),b('Es el oxidante porque gana electrones','Oxidatzailea da, elektroiak irabazten dituelako'),b('No es redox porque la carga cambia','Ez da erredox, karga aldatzen delako')],b('El reductor cede electrones y se oxida; el oxidante los acepta y se reduce.','Erreduktoreak elektroiak ematen ditu eta oxidatu egiten da; oxidatzaileak hartu eta erreduzitu egiten da.'));}
function q2roles(){return mcq(tag.pila,b('En una pila galvánica, ¿qué ocurre en el ánodo y cómo se mueven los electrones?','Pila galbaniko batean, zer gertatzen da anodoan eta nola mugitzen dira elektroiak?'),b('Oxidación; los electrones salen del ánodo hacia el cátodo','Oxidazioa; elektroiak anodotik katodora doaz'),[b('Reducción; los electrones salen del cátodo','Erredukzioa; elektroiak katodotik ateratzen dira'),b('Oxidación; los electrones van del cátodo al ánodo','Oxidazioa; elektroiak katodotik anodora doaz'),b('Reducción; no hay flujo electrónico','Erredukzioa; ez dago elektroi-fluxurik')],b('La oxidación siempre ocurre en el ánodo; en la pila los electrones recorren el circuito exterior hasta el cátodo.','Oxidazioa beti anodoan gertatzen da; pilan elektroiak kanpoko zirkuitutik katodora doaz.'));}
function q2pt(){return mcq(tag.pila,b('¿Qué notación representa correctamente un electrodo inerte para Fe³⁺/Fe²⁺?','Zein notaziok adierazten du behar bezala Fe³⁺/Fe²⁺ bikotearen elektrodo inertea?'),b('Pt(s) | Fe²⁺(aq), Fe³⁺(aq)','Pt(s) | Fe²⁺(aq), Fe³⁺(aq)'),[b('Fe³⁺ | Fe²⁺ sin electrodo','Fe³⁺ | Fe²⁺ elektrodorik gabe'),b('Pt(aq) | Fe(s)','Pt(aq) | Fe(s)'),b('Fe²⁺ | Fe³⁺ | Pt(aq)','Fe²⁺ | Fe³⁺ | Pt(aq)')],b('Pt(s) conduce electrones; Fe²⁺ y Fe³⁺ son especies disueltas y ninguna forma un electrodo sólido propio.','Pt(s)-k elektroiak eroaten ditu; Fe²⁺ eta Fe³⁺ disolbatuta daude, eta batek ere ez du bere elektrodo solidoa osatzen.'));}
function q2real(){return mcq(tag.pila,b('Para una pila Zn/Cu con E°red(Cu²⁺/Cu)=0,342 V y E°red(Zn²⁺/Zn)=−0,763 V, ¿cuál es E°pila?','Zn/Cu pila batean E°red(Cu²⁺/Cu)=0,342 V eta E°red(Zn²⁺/Zn)=−0,763 V badira, zein da E°pila?'),b('1,105 V','1,105 V'),[b('−0,421 V','−0,421 V'),b('0,763 V','0,763 V'),b('−1,105 V','−1,105 V')],b('El Cu es cátodo: E°pila=0,342−(−0,763)=1,105 V.','Cu katodoa da: E°pila=0,342−(−0,763)=1,105 V.'));}
function q3ion(){return mcq(tag.ner,b('Para Fe³⁺ + e⁻ ⇌ Fe²⁺, ¿qué cociente de reacción usa Nernst?','Fe³⁺ + e⁻ ⇌ Fe²⁺ erreakziorako, zein erreakzio-zatidura erabiltzen da Nernsten ekuazioan?'),b('[Fe²⁺]/[Fe³⁺]','[Fe²⁺]/[Fe³⁺]'),[b('[Fe³⁺]/[Fe²⁺]','[Fe³⁺]/[Fe²⁺]'),b('[Fe²⁺]·[Fe³⁺]','[Fe²⁺]·[Fe³⁺]'),b('1/[Fe²⁺]','1/[Fe²⁺]')],b('Los productos sobre reactivos dan Qred=[Fe²⁺]/[Fe³⁺]; el electrón no se incluye.','Produktuen eta erreaktiboen zatidurak Qred=[Fe²⁺]/[Fe³⁺] ematen du; elektroia ez da sartzen.'));}
function q3ph(){const ph=pick([1,2,3,4]),h=10**-ph,e=1.33-(S/6)*Math.log10((.01**2)/(.1*h**14));return nq(tag.ner,b(`Para Cr₂O₇²⁻/Cr³⁺ con E°=1,33 V, [Cr₂O₇²⁻]=0,10 M, [Cr³⁺]=0,010 M y pH=${ph}, calcula E (V).`,`Cr₂O₇²⁻/Cr³⁺ bikotean E°=1,33 V, [Cr₂O₇²⁻]=0,10 M, [Cr³⁺]=0,010 M eta pH=${ph} dira. Kalkulatu E (V).`),e,b(`Incluye [H⁺]¹⁴ en Q: con pH ${ph}, [H⁺]=10⁻${ph} M y E≈${fix(e,3)} V.`,`[H⁺]¹⁴ sartu Q-n: pH ${ph} denez, [H⁺]=10⁻${ph} M eta E≈${fix(e,3)} V.`),{abs:.002});}
function q3hydrogen(){const ph=pick([1,2,3,5]),e=-.0592*ph;return nq(tag.ner,b(`Una semicelda H⁺/H₂ tiene P(H₂)=1 atm y pH=${ph}. ¿Cuál es E (V) frente al electrodo estándar de hidrógeno?`,`H⁺/H₂ erdi-zelda batean P(H₂)=1 atm eta pH=${ph} dira. Zein da E (V) hidrogeno-elektrodo estandarrarekiko?`),e,b(`E=0,0592log[H⁺]=−0,0592·pH=−0,0592·${ph}=${fix(e,4)} V.`,`E=0,0592log[H⁺]=−0,0592·pH=−0,0592·${ph}=${fix(e,4)} V.`),{abs:.001});}
function q4time(){const I=pick([.02,.05,.10]),t=pick([60,240,900]),q=I*t;return nq(tag.far,b(`Una celda transporta I=${fix(I,2)} A durante ${t} s. ¿Qué carga Q (C) pasa por ella?`,`Zelula batetik I=${fix(I,2)} A igarotzen dira ${t} s-an. Zer karga Q (C) igarotzen da?`),q,b(`Q=It=${fix(I,2)}·${t}=${fix(q,2)} C.`,`Q=It=${fix(I,2)}·${t}=${fix(q,2)} C.`),{abs:.01});}
function q4electrons(){const I=pick([.01,.03,.08]),t=pick([100,500,1200]),n=pick([1,2,3]),mol=I*t/F,xi=mol/n;return nq(tag.far,b(`Una reacción de pila con n=${n} e⁻ por avance ocurre con I=${fix(I,2)} A durante ${t} s. Calcula el avance ξ (mol).`,`Pila-erreakzioak aurrerapen bakoitzeko n=${n} e⁻ trukatzen ditu, eta I=${fix(I,2)} A igarotzen dira ${t} s-an. Kalkulatu ξ aurrerapena (mol).`),xi,b(`ξ=It/(nF)=${fix(I,2)}·${t}/(${n}·96485)=${fix(xi,6)} mol.`,`ξ=It/(nF)=${fix(I,2)}·${t}/(${n}·96485)=${fix(xi,6)} mol.`),{abs:1e-7});}
function q5conc(){const hi=pick([.1,.5,1]),lo=pick([.001,.01,.02]),e=.0592*Math.log10(hi/lo);return nq(tag.pila,b(`Una pila de concentración Ag⁺/Ag tiene [Ag⁺]alta=${num(hi)} M y [Ag⁺]baja=${num(lo)} M. Calcula E (V) a 25 °C.`,`Ag⁺/Ag kontzentrazio-pilan [Ag⁺]kontz=${num(hi)} M eta [Ag⁺]dilu=${num(lo)} M dira. Kalkulatu E (V) 25 °C-an.`),e,b(`E=(0,0592)log(${num(hi)}/${num(lo)})=${fix(e,4)} V.`,`E=(0,0592)log(${num(hi)}/${num(lo)})=${fix(e,4)} V.`),{abs:.001});}
function q5kps(){const e=pick([.0592,.1184,.1776]),s=.1/10**(e/S),k=s*s;return nq(tag.pila,b(`Una pila de concentración Ag⁺/Ag tiene [Ag⁺]=0,100 M frente a AgBr saturado, y E=${fix(e,4)} V. Halla Kps(AgBr).`,`Ag⁺/Ag kontzentrazio-pilan [Ag⁺]=0,100 M dago AgBr-rekiko asea den erdi-zeldaren aurrean, eta E=${fix(e,4)} V da. Kalkulatu Kps(AgBr).`),k,b(`E=0,0592log(0,100/s) despeja s=${fix(s,5)} M; Kps=s²=${k.toExponential(2)}.`,`E=0,0592log(0,100/s) ebatzita s=${fix(s,5)} M; Kps=s²=${k.toExponential(2)}.`),{tol:.04});}
function q5silver(){const cl=pick([.01,.05,.1]),k=1.8e-10,ag=k/cl,e=.799+S*Math.log10(ag);return nq(tag.pila,b(`Tras precipitar AgCl, [Cl⁻]=${num(cl)} M y Kps=1,8×10⁻¹⁰. Calcula [Ag⁺] (M) y EAg (V).`,`AgCl hauspeatu ondoren, [Cl⁻]=${num(cl)} M eta Kps=1,8×10⁻¹⁰ dira. Kalkulatu [Ag⁺] (M) eta EAg (V).`),e,b(`[Ag⁺]=Kps/[Cl⁻]=${ag.toExponential(2)} M; E=0,799+0,0592log[Ag⁺]=${fix(e,3)} V.`,`[Ag⁺]=Kps/[Cl⁻]=${ag.toExponential(2)} M; E=0,799+0,0592log[Ag⁺]=${fix(e,3)} V.`),{abs:.002});}
function q5reverse(){return mcq(tag.pila,b('Tras precipitar el ion de uno de los electrodos, su E real cae por debajo del del otro. ¿Qué puede ocurrir?','Elektrodo bateko ioia hauspeatu ondoren, haren E erreala bestearena baino txikiagoa da. Zer gerta daiteke?'),b('La pila puede invertir espontáneamente su sentido','Pilak berez noranzkoa alda dezake'),[b('E° de todos los pares cambia','Bikote guztien E° aldatzen da'),b('La pila deja de obedecer Nernst','Pilak Nernsten ekuazioa betetzeari uzten dio'),b('La precipitación no puede afectar E','Hauspeaketak ezin du E aldatu')],b('La precipitación modifica la concentración libre y, por Nernst, puede cambiar qué electrodo tiene mayor E real.','Hauspeaketak ioi askearen kontzentrazioa aldatzen du; Nernsten arabera, E erreal handiena duen elektrodoa ere alda daiteke.'));}
function q5sulfide(){return mcq(tag.pila,b('En PbSO₄(s) ⇌ Pb²⁺ + SO₄²⁻, si el sólido está en equilibrio con la disolución, ¿qué relación se cumple?','PbSO₄(s) ⇌ Pb²⁺ + SO₄²⁻ orekan badago, zein erlazio betetzen da?'),b('[Pb²⁺][SO₄²⁻]=Kps','[Pb²⁺][SO₄²⁻]=Kps'),[b('[Pb²⁺]+[SO₄²⁻]=Kps','[Pb²⁺]+[SO₄²⁻]=Kps'),b('[Pb²⁺]/[SO₄²⁻]=Kps','[Pb²⁺]/[SO₄²⁻]=Kps'),b('[Pb²⁺][SO₄²⁻]=0','[Pb²⁺][SO₄²⁻]=0')],b('Los exponentes de Kps proceden de los coeficientes estequiométricos; la actividad del sólido puro vale 1.','Kps-en berretzaileak koefiziente estekiometrikoetatik datoz; solido puruaren aktibitatea 1 da.'));}
function q6passive(){return mcq(tag.corr,b('¿Por qué el aluminio puede resistir la corrosión aunque su oxidación sea termodinámicamente favorable?','Zergatik izan daiteke aluminioa korrosioarekiko erresistentea, haren oxidazioa termodinamikoki faboragarria izan arren?'),b('La capa compacta de Al₂O₃ pasiva la superficie y frena la reacción','Al₂O₃ geruza trinkoak gainazala pasibatu eta erreakzioa moteltzen du'),[b('Su potencial de reducción es siempre positivo','Erredukzio-potentziala beti positiboa delako'),b('El aluminio no conduce electrones','Aluminioak elektroiak eroaten ez dituelako'),b('El oxígeno deja de ser oxidante','Oxigenoa oxidatzaile izateari uzten diolako')],b('La termodinámica predice la tendencia, pero la capa de óxido dificulta cinéticamente la corrosión posterior.','Termodinamikak joera adierazten du, baina oxido-geruzak ondorengo korrosioa zinetikoki oztopatzen du.'));}
function q6battery(){return mcq(tag.corr,b('¿Qué conversión ocurre durante la descarga de una batería de plomo-ácido?','Berun-azido bateria deskargatzean, zer bihurketa gertatzen da?'),b('Pb y PbO₂ se convierten en PbSO₄ y se consume H₂SO₄','Pb eta PbO₂ PbSO₄ bihurtzen dira, eta H₂SO₄ kontsumitzen da'),[b('PbSO₄ se convierte en LiCoO₂','PbSO₄ LiCoO₂ bihurtzen da'),b('Solo se consume agua; los electrodos no cambian','Ura bakarrik kontsumitzen da; elektrodoak ez dira aldatzen'),b('El zinc se oxida y Ag₂O se reduce','Zinka oxidatu eta Ag₂O erreduzitzen da')],b('En la descarga ambos electrodos forman PbSO₄; la reacción global consume ácido sulfúrico.','Deskargan bi elektrodoek PbSO₄ sortzen dute; erreakzio globalak azido sulfurikoa kontsumitzen du.'));}
function q6oxygen(){return mcq(tag.corr,b('En la corrosión del hierro húmedo, ¿qué especie suele aceptar los electrones en el cátodo?','Burdina hezearen korrosioan, zein espeziek hartzen ditu normalean elektroiak katodoan?'),b('El oxígeno disuelto, que se reduce','Disolbatutako oxigenoak, erreduzitu egiten baita'),[b('El hierro metálico, que se oxida','Burdina metalikoak, oxidatu egiten baita'),b('El nitrógeno, que forma Fe³⁺','Nitrogenoak, Fe³⁺ sortzen baitu'),b('El agua, que siempre se oxida a O₂','Urak, beti O₂-ra oxidatzen baita')],b('Las zonas anódicas disuelven Fe; en zonas catódicas el O₂ se reduce en presencia de agua.','Eremu anodikoetan Fe disolbatzen da; eremu katodikoetan O₂ erreduzitzen da uraren presentzian.'));}
function q6dry(){return mcq(tag.corr,b('¿Qué caracteriza a la pila de Leclanché comercial?','Zerk bereizten du Leclanché pila komertziala?'),b('Es una pila seca con electrolito en pasta y tensión nominal cercana a 1,5 V','Pila lehorra da, elektrolitoa pastan du eta 1,5 V inguruko tentsio nominala'),[b('Usa una disolución líquida de litio y entrega 3,4 V','Litio-disoluzio likidoa erabiltzen du eta 3,4 V ematen ditu'),b('Es una pila de combustible de H₂/O₂','H₂/O₂ erregai-pila da'),b('Su electrolito es H₂SO₄ concentrado','H₂SO₄ kontzentratua du elektrolito')],b('La celda Zn/MnO₂ de Leclanché lleva el electrolito como pasta; por eso se llama pila seca.','Leclanché-ren Zn/MnO₂ zelulak elektrolitoa pasta moduan du; horregatik esaten zaio pila lehorra.'));}
function pickN(a,n){return shuf(a).slice(0,n);}

