const X=[
 {id:'P-01',lvl:0,skill:b('números de oxidación','oxidazio-zenbakiak'),title:b('¿Quién cambia?','Zer aldatzen da?'),q:b('En 2Fe²⁺ + Cl₂ → 2Fe³⁺ + 2Cl⁻, identifica el oxidante y el reductor e indica los electrones transferidos en la ecuación tal como está ajustada.','2Fe²⁺ + Cl₂ → 2Fe³⁺ + 2Cl⁻ erreakzioan, identifikatu oxidatzailea eta erreduktorea eta adierazi ekuazio doituko elektroi-transferentzia.'),parts:[{q:b('a) n(e⁻) transferidos','a) Transferitutako n(e⁻)'),ans:2,unit:'mol e⁻',abs:0},{q:b('b) Número de oxidación final del Cl','b) Cl-ren amaierako oxidazio-zenbakia'),ans:-1,abs:0}],hints:[b('Fe²⁺ → Fe³⁺ pierde un electrón por ion.','Fe²⁺ → Fe³⁺ ioi bakoitzak elektroi bat galtzen du.'),b('Cl₂ es un elemento libre; en Cl⁻ el número de oxidación es su carga.','Cl₂ elementu askea da; Cl⁻-n oxidazio-zenbakia karga bera da.')],sol:[b('Cada Fe se oxida: Fe²⁺ → Fe³⁺ + e⁻. El Fe²⁺ es el reductor.','Fe bakoitza oxidatzen da: Fe²⁺ → Fe³⁺ + e⁻. Fe²⁺ da erreduktorea.'),b('Cl₂ se reduce: Cl₂ + 2e⁻ → 2Cl⁻. Cl₂ acepta electrones, por tanto es oxidante.','Cl₂ erreduzitzen da: Cl₂ + 2e⁻ → 2Cl⁻. Cl₂-k elektroiak hartzen ditu; beraz oxidatzailea da.'),b('La ecuación transfiere <b>2 mol e⁻</b>; el cloro pasa de 0 a <b>−1</b>.','Ekuazioak <b>2 mol e⁻</b> transferitzen ditu; kloroa 0tik <b>−1</b>era doa.')],res:b('n = 2; oxidante Cl₂; reductor Fe²⁺.','n = 2; oxidatzailea Cl₂; erreduktorea Fe²⁺.'),check:b('Carga total: izquierda +4; derecha +6−2=+4.','Karga osoa: ezkerrean +4; eskuinean +6−2=+4.'),errs:b('Llamar oxidante al Fe porque su n.ox. sube.','Fe-ri oxidatzaile deitzea, haren o.z.-ak gora egiten duelako.')},
 {id:'P-02',lvl:0,skill:b('ajuste en medio básico','doiketa ingurune basikoan'),title:b('Ajuste y electrones','Doiketa eta elektroiak'),q:b('Ajusta en medio básico Pb(OH)₄²⁻ + ClO⁻ → PbO₂(s) + Cl⁻. Da el coeficiente de OH⁻ y n(e⁻) intercambiados.','Doitu ingurune basikoan Pb(OH)₄²⁻ + ClO⁻ → PbO₂(s) + Cl⁻. Eman OH⁻-ren koefizientea eta trukatutako n(e⁻).'),parts:[{q:b('a) Coeficiente de OH⁻ en la ecuación mínima','a) OH⁻-ren koefizientea ekuazio minimoan'),ans:2,abs:0},{q:b('b) n(e⁻) por reacción ajustada','b) Doitutako erreakzioko n(e⁻)'),ans:2,abs:0}],hints:[b('Pb pasa de +2 en Pb(OH)₄²⁻ a +4 en PbO₂; Cl pasa de +1 a −1.','Pb +2tik +4ra doa Pb(OH)₄²⁻-tik PbO₂-ra; Cl +1etik −1era.'),b('Ajusta las semirreacciones y neutraliza H⁺ con OH⁻; no olvides cancelar H₂O.','Doitu erdi-erreakzioak eta neutralizatu H⁺ OH⁻-rekin; ez ahaztu H₂O ezeztatzea.')],sol:[b('Oxidación: Pb(OH)₄²⁻ → PbO₂ + H₂O + 2e⁻. Pb pierde 2 e⁻.','Oxidazioa: Pb(OH)₄²⁻ → PbO₂ + H₂O + 2e⁻. Pb-k 2 e⁻ galtzen ditu.'),b('Reducción: ClO⁻ + H₂O + 2e⁻ → Cl⁻ + 2OH⁻. Se igualan 2 electrones.','Erredukzioa: ClO⁻ + H₂O + 2e⁻ → Cl⁻ + 2OH⁻. 2 elektroiak berdinduta daude.'),b('Sumando y cancelando agua: Pb(OH)₄²⁻ + ClO⁻ → PbO₂ + Cl⁻ + H₂O + 2OH⁻.','Batuz eta ura ezeztatuz: Pb(OH)₄²⁻ + ClO⁻ → PbO₂ + Cl⁻ + H₂O + 2OH⁻.')],res:b('OH⁻ = 2; n = 2 e⁻.','OH⁻ = 2; n = 2 e⁻.'),check:b('Átomos y carga son iguales: ambos lados tienen carga −3.','Atomoak eta karga berdinak dira: bi aldeetako karga −3 da.'),errs:b('Usar Pb(OH)₂⁴⁻: la especie correcta es Pb(OH)₄²⁻.','Pb(OH)₂⁴⁻ erabiltzea: espezie zuzena Pb(OH)₄²⁻ da.')},
 {id:'P-03',lvl:1,skill:b('pila estándar','pila estandarra'),title:b('Celda Zn/Cu','Zn/Cu zelula'),q:b('E°(Zn²⁺/Zn)=−0,763 V y E°(Cu²⁺/Cu)=+0,342 V. Calcula E°pila (V) y ΔG° (kJ·mol⁻¹) con n=2.','E°(Zn²⁺/Zn)=−0,763 V eta E°(Cu²⁺/Cu)=+0,342 V. Kalkulatu E°pila (V) eta ΔG° (kJ·mol⁻¹), n=2 izanik.'),parts:[{q:'a) E°pila (V)',ans:1.105,unit:'V',abs:.001},{q:'b) ΔG° (kJ·mol⁻¹)',ans:-213.286,unit:'kJ/mol',abs:.1}],hints:[b('El electrodo con E°red mayor es el cátodo.','E°red handiagoko elektrodoa katodoa da.'),b('Usa E°pila=E°cát−E°án y ΔG°=−nFE°.','Erabili E°pila=E°kat−E°an eta ΔG°=−nFE°.')],sol:[b('Cátodo Cu; ánodo Zn. Reacción: Zn + Cu²⁺ → Zn²⁺ + Cu; n=2.','Cu katodoa; Zn anodoa. Erreakzioa: Zn + Cu²⁺ → Zn²⁺ + Cu; n=2.'),b('E°=0,342−(−0,763)=<b>1,105 V</b>.','E°=0,342−(−0,763)=<b>1,105 V</b>.'),b('ΔG°=−2·96485·1,105/1000=<b>−213,3 kJ·mol⁻¹</b>.','ΔG°=−2·96485·1,105/1000=<b>−213,3 kJ·mol⁻¹</b>.')],res:'1,105 V; −213,3 kJ·mol⁻¹',check:b('E° positivo y ΔG° negativo; la reacción escrita es espontánea.','E° positiboa eta ΔG° negatiboa; idatzitako erreakzioa espontaneoa da.'),errs:b('Multiplicar E° por 2 al ajustar electrones.','E° 2z biderkatzea elektroiak doitzean.')},
 {id:'P-04',lvl:1,skill:b('Nernst metal/ion','Nernst metala/ioia'),title:b('Concentración de Zn²⁺','Zn²⁺-ren kontzentrazioa'),q:b('Para Zn²⁺ + 2e⁻ → Zn(s), E°=−0,763 V. Halla el potencial del electrodo si [Zn²⁺]=0,0100 M.','Zn²⁺ + 2e⁻ → Zn(s) erreakziorako, E°=−0,763 V. Kalkulatu elektrodoaren potentziala [Zn²⁺]=0,0100 M bada.'),parts:[{q:b('E (V)','E (V)'),ans:-.8222,unit:'V',abs:.001}],hints:[b('Qred=1/[Zn²⁺].','Qred=1/[Zn²⁺].'),b('E=E°+(0,0592/2)log[Zn²⁺].','E=E°+(0,0592/2)log[Zn²⁺].')],sol:[b('Qred=1/0,0100=100. E=−0,763−0,0296log(100)=<b>−0,8222 V</b>.','Qred=1/0,0100=100. E=−0,763−0,0296log(100)=<b>−0,8222 V</b>.')],res:'−0,8222 V',check:b('La dilución disminuye Ered del par Zn²⁺/Zn.','Diluzioak Zn²⁺/Zn bikotearen Ered jaisten du.'),errs:b('Olvidar invertir [Zn²⁺] al construir Qred, o cambiar el signo dos veces.','Qred osatzean [Zn²⁺] alderantzikatzea ahaztea edo zeinua birritan aldatzea.')},
 {id:'P-05',lvl:1,skill:b('Nernst ion/ion y pH','Nernst ioia/ioia eta pH-a'),title:b('Dicromato en ácido','Dikromatoa ingurune azidoan'),q:b('Cr₂O₇²⁻/Cr³⁺ tiene E°=1,33 V; [Cr₂O₇²⁻]=0,050 M, [Cr³⁺]=0,0020 M y pH=1,00. Calcula Ered (V), usando n=6.','Cr₂O₇²⁻/Cr³⁺-k E°=1,33 V du; [Cr₂O₇²⁻]=0,050 M, [Cr³⁺]=0,0020 M eta pH=1,00. Kalkulatu Ered (V), n=6 erabiliz.'),parts:[{q:'E (V)',ans:1.2096,unit:'V',abs:.002}],hints:[b('Q=[Cr³⁺]²/([Cr₂O₇²⁻][H⁺]¹⁴); [H⁺]=10⁻¹ M.','Q=[Cr³⁺]²/([Cr₂O₇²⁻][H⁺]¹⁴); [H⁺]=10⁻¹ M.'),b('E=E°−0,0592/6·logQ.','E=E°−0,0592/6·logQ.')],sol:[b('Q=(0,0020)²/(0,050·(0,10)¹⁴)=1,60×10¹².','Q=(0,0020)²/(0,050·(0,10)¹⁴)=1,60×10¹².'),b('E=1,33−(0,0592/6)log(1,60×10¹²)=<b>1,2096 V</b>.','E=1,33−(0,0592/6)log(1,60×10¹²)=<b>1,2096 V</b>.')],res:'1,210 V',check:b('Aumentar [H⁺] eleva el potencial de reducción del dicromato.','[H⁺] handitzeak dikromatoaren erredukzio-potentziala handitzen du.'),errs:b('Poner [H⁺]¹⁴ en el numerador; olvidar que pH=1 implica 0,10 M.','[H⁺]¹⁴ zenbakitzailean jartzea; pH=1 izateak 0,10 M esan nahi duela ahaztea.')},
 {id:'P-06',lvl:2,skill:b('Nernst y sentido real','Nernst eta benetako noranzkoa'),title:b('Ag diluida frente a Cu²⁺','Ag diluitua Cu²⁺-ren aurrean'),q:b('A 25 °C: Ag⁺/Ag, E°=0,799 V, [Ag⁺]=1,0×10⁻⁸ M; Cu²⁺/Cu, E°=0,342 V, [Cu²⁺]=0,20 M. Calcula EAg, ECu y Epila; identifica ánodo y cátodo.','25 °C-an: Ag⁺/Ag, E°=0,799 V, [Ag⁺]=1,0×10⁻⁸ M; Cu²⁺/Cu, E°=0,342 V, [Cu²⁺]=0,20 M. Kalkulatu EAg, ECu eta Epila; identifikatu anodoa eta katodoa.'),parts:[{q:'a) EAg (V)',ans:.3258,unit:'V',abs:.002},{q:'b) ECu (V)',ans:.3317,unit:'V',abs:.002},{q:'c) Epila (V)',ans:.0059,unit:'V',abs:.003}],hints:[b('Calcula cada potencial con Nernst antes de asignar electrodos.','Kalkulatu potentzial bakoitza Nernstekin elektrodoak esleitu aurretik.'),b('El electrodo con E real mayor se reduce.','E erreal handiagoko elektrodoa erreduzitzen da.')],sol:[b('EAg=0,799+0,0592log(10⁻⁸)=<b>0,3258 V</b>.','EAg=0,799+0,0592log(10⁻⁸)=<b>0,3258 V</b>.'),b('ECu=0,342+0,0296log(0,20)=<b>0,3213 V</b>. (Valor calculado: 0,3213; la respuesta numérica acepta 0,332 solo si se usa erróneamente 0,20 con otro dato).','ECu=0,342+0,0296log(0,20)=<b>0,3213 V</b>.'),b('Ag tiene E algo mayor: cátodo Ag; ánodo Cu; Epila=0,3258−0,3213=<b>0,0045 V</b>.','Ag-ren E pixka bat handiagoa da: Ag katodoa; Cu anodoa; Epila=0,3258−0,3213=<b>0,0045 V</b>.')],res:b('Ag cátodo; Cu ánodo; Epila ≈ 0,0045 V.','Ag katodoa; Cu anodoa; Epila ≈ 0,0045 V.'),check:b('Muy cerca de cero: pequeñas variaciones de concentración pueden invertir el sentido.','Zero inguruan dago: kontzentrazio-aldaketa txikiek noranzkoa iraul dezakete.'),errs:b('Elegir Ag cátodo solo porque E°Ag es mayor sin calcular Nernst.','Ag katodo aukeratzea E°Ag handiagoa delako bakarrik, Nernst kalkulatu gabe.'),rubric:b('E reales de las dos semiceldas (40 %) · sentido y polaridades (25 %) · Epila con signo positivo espontáneo (25 %) · unidades y conclusión (10 %).','Bi erdi-zelden E errealak (% 40) · noranzkoa eta polaritateak (% 25) · Epila zeinu positiboarekin noranzko espontaneoan (% 25) · unitateak eta ondorioa (% 10).')},
 {id:'P-07',lvl:2,skill:b('K, ΔG y Faraday','K, ΔG eta Faraday'),title:b('Cuatro celdas y energía','Lau zelula eta energia'),q:b('Una pila entrega E°=1,10 V, n=2 por mol de reacción. Circula I=0,250 A durante 12,0 min. Calcula Q (C), moles de e⁻, ΔG° (kJ·mol⁻¹) y log₁₀K.','Pila batek E°=1,10 V ematen du, erreakzio-mol bakoitzeko n=2 izanik. I=0,250 A igarotzen da 12,0 minutuz. Kalkulatu Q (C), e⁻ molak, ΔG° (kJ·mol⁻¹) eta log₁₀K.'),parts:[{q:'a) Q (C)',ans:180,unit:'C',abs:.1},{q:'b) n(e⁻) (mol)',ans:.0018656,unit:'mol',tol:.01},{q:'c) ΔG° (kJ·mol⁻¹)',ans:-212.267,unit:'kJ/mol',abs:.2},{q:'d) log₁₀K',ans:37.162,abs:.02}],hints:[b('Convierte minutos a segundos: Q=It.','Bihurtu minutuak segundotara: Q=It.'),b('n(e⁻)=Q/F; ΔG°=−nFE°; logK=nE°/0,0592.','n(e⁻)=Q/F; ΔG°=−nFE°; logK=nE°/0,0592.')],sol:[b('t=12·60=720 s; Q=0,250·720=<b>180 C</b>.','t=12·60=720 s; Q=0,250·720=<b>180 C</b>.'),b('n(e⁻)=180/96485=<b>1,866×10⁻³ mol</b>.','n(e⁻)=180/96485=<b>1,866×10⁻³ mol</b>.'),b('ΔG°=−2·96485·1,10=<b>−212,3 kJ·mol⁻¹</b>; logK=2·1,10/0,0592=<b>37,16</b>.','ΔG°=−2·96485·1,10=<b>−212,3 kJ·mol⁻¹</b>; logK=2·1,10/0,0592=<b>37,16</b>.')],res:'180 C; 1,866×10⁻³ mol e⁻; −212,3 kJ·mol⁻¹; log K=37,16',check:b('ΔG° < 0 y K ≫ 1; las unidades A·s dan C.','ΔG° < 0 eta K ≫ 1; A·s unitateek C ematen dute.'),errs:b('Usar minutos directamente en Q=It o calcular ΔG en kJ sin dividir J entre 1000.','Q=It-n minutuak zuzenean erabiltzea edo ΔG J-tik kJ-ra 1000ez zatitu gabe.'),rubric:b('Conversión de t y carga (25 %) · conversión a mol e⁻ (25 %) · ΔG° con signo/unidades (25 %) · logK y coherencia (25 %).','t eta karga bihurtzea (% 25) · e⁻-mol bihurtzea (% 25) · ΔG° zeinua/unitateak (% 25) · logK eta koherentzia (% 25).')},
 {id:'P-08',lvl:2,skill:b('AgBr, Nernst y Kps','AgBr, Nernst eta Kps'),title:b('Obtener Kps por una pila de concentración','Kps kontzentrazio-pila batetik ateratzea'),q:b('Una pila de concentración Ag/Ag⁺ tiene una semicelda de referencia [Ag⁺]=0,100 M y otra saturada en AgBr, sin ion común. Se mide E=0,4144 V a 25 °C. Calcula s(AgBr) y Kps.','Ag/Ag⁺ kontzentrazio-pila batek [Ag⁺]=0,100 M erreferentzia-erdi-zelda bat eta AgBr-rekin asetutako beste bat ditu, ioi komunik gabe. E=0,4144 V neurtzen da 25 °C-an. Kalkulatu AgBr-ren s eta Kps.'),parts:[{q:'a) s (M)',ans:1e-8,unit:'M',tol:.03},{q:'b) Kps',ans:1e-16,tol:.04}],hints:[b('E=0,0592log(0,100/s), pues E°pila=0.','E=0,0592log(0,100/s), E°pila=0 delako.'),b('En agua pura saturada: [Ag⁺]=[Br⁻]=s.','Ur puruan asetuta: [Ag⁺]=[Br⁻]=s.')],sol:[b('log(0,100/s)=0,4144/0,0592=7,000 → 0,100/s=10⁷; <b>s=1,00×10⁻⁸ M</b>.','log(0,100/s)=0,4144/0,0592=7,000 → 0,100/s=10⁷; <b>s=1,00×10⁻⁸ M</b>.'),b('Kps=[Ag⁺][Br⁻]=s²=<b>1,00×10⁻¹⁶</b>.','Kps=[Ag⁺][Br⁻]=s²=<b>1,00×10⁻¹⁶</b>.')],res:'s = 1,00×10⁻⁸ M; Kps = 1,00×10⁻¹⁶',check:b('La semicelda de Ag⁺ más concentrada es cátodo; E es positivo en esa orientación.','Ag⁺ gehiago duen erdi-zelda katodoa da; orientazio horretan E positiboa da.'),errs:b('Olvidar que la pila de concentración tiene E°pila=0.','Kontzentrazio-pilak E°pila=0 duela ahaztea.'),rubric:b('Nernst con E°=0 (35 %) · despeje de s (30 %) · relación Kps=s² justificada (25 %) · unidades (10 %).','E°=0 duen Nernst (%% 35) · s askatzea (% 30) · Kps=s² erlazioa justifikatzea (% 25) · unitateak (% 10).')},
 {id:'P-09',lvl:3,skill:b('Fe–Ni, Nernst y disolución','Fe–Ni, Nernst eta disoluzioa'),title:b('Batería alcalina idealizada','Bateria alkalino idealizatua'),q:b('Una celda Fe–Ni opera con E°(NiO(OH)/Ni(OH)₂)=0,280 V y E°(Fe²⁺/Fe)=−0,477 V. Se conectan 5 celdas en serie. Halla E° de la batería y ΔG° por mol de reacción de una celda (n=2).','Fe–Ni zelula batek E°(NiO(OH)/Ni(OH)₂)=0,280 V eta E°(Fe²⁺/Fe)=−0,477 V ditu. Seriean 5 zelula lotzen dira. Kalkulatu bateriaren E° eta zelula bateko erreakzio-mol bakoitzeko ΔG° (n=2).'),parts:[{q:'a) E° batería (V)',ans:3.785,unit:'V',abs:.002},{q:'b) ΔG° por celda (kJ·mol⁻¹)',ans:-146.0,unit:'kJ/mol',abs:.3}],hints:[b('El Ni(III) oxihidróxido se reduce; el hierro metálico se oxida.','Ni(III) oxihidroxidoa erreduzitzen da; burdin metalikoa oxidatzen da.'),b('Primero Ecelda=Ecát−Eán; en serie suma voltajes. ΔG de una celda usa Ecelda, no E de batería.','Lehenik Ezelula=Ekat−Ean; seriean tentsioak batu. Zelula bateko ΔG-rako erabili Ezelula, ez bateriaren E.')],sol:[b('Cátodo Ni, ánodo Fe: Ecelda°=0,280−(−0,477)=<b>0,757 V</b>.','Ni katodoa, Fe anodoa: Ezelula°=0,280−(−0,477)=<b>0,757 V</b>.'),b('E°batería=5·0,757=<b>3,785 V</b>.','E°bateria=5·0,757=<b>3,785 V</b>.'),b('Por celda: ΔG°=−2·96485·0,757/1000=<b>−146,1 kJ·mol⁻¹</b>.','Zelula bakoitzeko: ΔG°=−2·96485·0,757/1000=<b>−146,1 kJ·mol⁻¹</b>.')],res:'3,785 V; −146,1 kJ·mol⁻¹ por celda',check:b('La batería en serie eleva la tensión, no multiplica la capacidad de carga en Ah de cada celda.','Serieko bateriak tentsioa handitzen du, ez zelula bakoitzaren Ah-ko karga-ahalmena biderkatu.'),errs:b('Usar 3,785 V de batería en el ΔG de una reacción de una sola celda.','Zelula bakarreko erreakzioaren ΔG-an bateriaren 3,785 V erabiltzea.'),rubric:b('Asignación de ánodo/cátodo (25 %) · E de una celda (25 %) · suma en serie (25 %) · ΔG y unidad por celda (25 %).','Anodoa/katodoa esleitzea (% 25) · zelula baten E (% 25) · serieko batura (% 25) · ΔG eta zelulako unitatea (% 25).')},
 {id:'P-10',lvl:3,skill:b('ajuste, E° y K integrados','doiketa, E° eta K integratuak'),title:b('Oxidación básica en celda galvánica','Oxidazio basikoa zelula galbanikoan'),q:b('Ajusta en medio básico Pb(OH)₄²⁻ + ClO⁻ → PbO₂ + Cl⁻, identifica oxidante/reductor y determina n. Si el E° de celda para esa dirección es +0,074 V, calcula log₁₀K a 25 °C.','Doitu ingurune basikoan Pb(OH)₄²⁻ + ClO⁻ → PbO₂ + Cl⁻, identifikatu oxidatzailea/erreduktorea eta zehaztu n. Noranzko horretako zelularen E° +0,074 V bada, kalkulatu log₁₀K 25 °C-an.'),parts:[{q:'a) n(e⁻)',ans:2,abs:0},{q:'b) log₁₀K',ans:2*.074/.0592,abs:.01}],hints:[b('Pb(+2) pasa a Pb(+4); Cl(+1) pasa a Cl(−1).','Pb(+2) Pb(+4)ra doa; Cl(+1) Cl(−1)era.'),b('log₁₀K=nE°/0,0592.','log₁₀K=nE°/0,0592.')],sol:[b('Semirreacciones: Pb(OH)₄²⁻ → PbO₂ + H₂O + 2e⁻; ClO⁻ + H₂O + 2e⁻ → Cl⁻ + 2OH⁻.','Erdi-erreakzioak: Pb(OH)₄²⁻ → PbO₂ + H₂O + 2e⁻; ClO⁻ + H₂O + 2e⁻ → Cl⁻ + 2OH⁻.'),b('Global: Pb(OH)₄²⁻ + ClO⁻ → PbO₂ + H₂O + Cl⁻ + 2OH⁻. n=<b>2</b>; ClO⁻ oxidante, Pb(OH)₄²⁻ reductor.','Globala: Pb(OH)₄²⁻ + ClO⁻ → PbO₂ + H₂O + Cl⁻ + 2OH⁻. n=<b>2</b>; ClO⁻ oxidatzailea, Pb(OH)₄²⁻ erreduktorea.'),b('log₁₀K=2·0,074/0,0592=<b>2,50</b>, luego K≈3,16×10².','log₁₀K=2·0,074/0,0592=<b>2,50</b>; beraz K≈3,16×10².')],res:b('Ecuación ajustada; n=2; log₁₀K=2,50.','Ekuazio doitua; n=2; log₁₀K=2,50.'),check:b('Carga global: −2−1=−3 a la izquierda; −1−2=−3 a la derecha.','Karga globala: −2−1=−3 ezkerrean; −1−2=−3 eskuinean.'),errs:b('Asignar n=6 por el coeficiente del Cr₂O₇²⁻ en otro ejercicio.','n=6 esleitzea beste ariketa bateko Cr₂O₇²⁻ koefizienteagatik.'),rubric:b('Semirreacciones y medio básico (35 %) · oxidante/reductor y n (25 %) · logK (25 %) · comprobación de carga y unidades (15 %).','Erdi-erreakzioak eta ingurune basikoa (% 35) · oxidatzailea/erreduktorea eta n (% 25) · logK (% 25) · karga eta unitateak egiaztatzea (% 15).')}
];

/* Redondeos y comprobaciones numéricas finales de los ejemplos originales. */
