nerExample[1].steps[0]=b('Plata: EAg = 0,799 + 0,0592log(10⁻⁸) = <b>0,3254 V</b>.','Zilarra: EAg = 0,799 + 0,0592log(10⁻⁸) = <b>0,3254 V</b>.');
