p9.title=b('Batería Fe–Ni en KOH','Fe–Ni bateria KOH-an');p9.skill=b('Fe–Ni, Nernst y medio alcalino','Fe–Ni, Nernst eta ingurune basikoa');
p9.q=b('Una celda Fe–Ni funciona en KOH saturado de Fe(OH)₂, con Kps=1,0×10⁻¹⁵. Usa E°(NiO(OH)/Ni(OH)₂)=0,280 V y E°(Fe²⁺/Fe)=−0,477 V. Calcula Ecelda y E de una batería de 5 celdas en serie, además de ΔG por mol de reacción de una celda (n=2). Comprueba que el potencial no depende de [OH⁻] comparando 1,0 M y 4,25 M.','Fe–Ni zelula batek Fe(OH)₂-rekiko asea den KOH-disoluzioan funtzionatzen du; Kps=1,0×10⁻¹⁵. Erabili E°(NiO(OH)/Ni(OH)₂)=0,280 V eta E°(Fe²⁺/Fe)=−0,477 V. Kalkulatu Ezelula, seriean lotutako 5 zelulako bateriaren E eta zelula bateko erreakzio-mol bakoitzeko ΔG (n=2). Egiaztatu potentziala [OH⁻]-ren independentea dela 1,0 M eta 4,25 M alderatuz.');
p9.parts=[{q:'a) E batería (V)',ans:6.005,unit:'V',abs:.003},{q:'b) ΔG por celda (kJ·mol⁻¹)',ans:-231.8,unit:'kJ/mol',abs:.2}];
p9.parts[0].q=b('a) E de la batería (V)','a) Bateriaren E (V)');p9.parts[1].q=b('b) ΔG por celda (kJ·mol⁻¹)','b) Zelula bakoitzeko ΔG (kJ·mol⁻¹)');
p9.hints=[b('En cada caso, [Fe²⁺]=Kps/[OH⁻]². Para NiO(OH)/Ni(OH)₂, E=0,280−0,0592log[OH⁻].','Kasu bakoitzean, [Fe²⁺]=Kps/[OH⁻]² da. NiO(OH)/Ni(OH)₂ bikoterako, E=0,280−0,0592log[OH⁻].'),b('Calcula los dos potenciales reales con cada [OH⁻]. Al sumar Ecelda y ΔG, usa n=2 por reacción de una celda.','Kalkulatu bi potentzial errealak [OH⁻] bakoitzarekin. Ezelula eta ΔG kalkulatzean, erabili n=2 zelula bateko erreakzio bakoitzeko.')];
p9.sol=[b('Con [OH⁻]=1,0 M: [Fe²⁺]=1,0×10⁻¹⁵ M y EFe=−0,477+0,0296log(1,0×10⁻¹⁵)=−0,921 V. ENi=0,280−0,0592log(1,0)=0,280 V. Ecelda=0,280−(−0,921)=1,201 V.','[OH⁻]=1,0 M denean: [Fe²⁺]=1,0×10⁻¹⁵ M eta EFe=−0,477+0,0296log(1,0×10⁻¹⁵)=−0,921 V. ENi=0,280−0,0592log(1,0)=0,280 V. Ezelula=0,280−(−0,921)=1,201 V.'),b('Con [OH⁻]=4,25 M: [Fe²⁺]=1,0×10⁻¹⁵/(4,25)²; EFe≈−0,958 V y ENi≈0,243 V. Ecelda≈0,243−(−0,958)=1,201 V: ambos E se desplazan igual y la diferencia no cambia.','[OH⁻]=4,25 M denean: [Fe²⁺]=1,0×10⁻¹⁵/(4,25)²; EFe≈−0,958 V eta ENi≈0,243 V. Ezelula≈0,243−(−0,958)=1,201 V: bi E-ak neurri berean desplazatzen dira, eta bien arteko diferentzia ez da aldatzen.'),b('E batería=5·1,201=<b>6,005 V</b>. Por celda, ΔG=−2·96 485·1,201/1000=<b>−231,8 kJ·mol⁻¹</b>.','E bateria=5·1,201=<b>6,005 V</b>. Zelula bakoitzeko, ΔG=−2·96 485·1,201/1000=<b>−231,8 kJ·mol⁻¹</b>.')];
p9.res=b('Ecelda=1,201 V; E batería=6,005 V; ΔG por celda=−231,8 kJ·mol⁻¹; el Ecelda es independiente de [OH⁻].','Ezelula=1,201 V; E bateria=6,005 V; zelula bakoitzeko ΔG=−231,8 kJ·mol⁻¹; Ezelula [OH⁻]-rekiko independentea da.');
p9.check=b('Al elevar [OH⁻], EFe baja y ENi también; los términos −0,0592log[OH⁻] se cancelan en la diferencia.','[OH⁻] handitzean, EFe eta ENi jaisten dira; −0,0592log[OH⁻] terminoak diferentzian ezeztatzen dira.');
p9.errs=b('Usar la tensión de la batería para calcular ΔG de una celda, o suponer que la misma [OH⁻] cambia la pila neta.','Bateria-tentsioa zelula bateko ΔG kalkulatzeko erabiltzea, edo [OH⁻] berak pila osoaren potentziala aldatzen duela pentsatzea.');
p9.rubric=b('Nernst para ambos electrodos (30 %) · comprobación con dos [OH⁻] (30 %) · serie y E batería (20 %) · ΔG de una celda con unidades (20 %).','Bi elektrodoetarako Nernst (% 30) · bi [OH⁻]-rekin egiaztatzea (% 30) · seriea eta bateria-E (% 20) · zelula bateko ΔG unitateekin (% 20).');
